module.exports = "<section class=\"bmb_chat-bubble\">\n  <section class=\"bmb_chat-bubble-main\">\n    <div\n      class=\"bmb_chat-bubble-main-info\"\n      [ngClass]=\"{\n        'bmb_chat-bubble-user': message().isUserMessage\n      }\"\n    >\n      <div\n        class=\"bmb_chat-bubble-profile\"\n        [ngClass]=\"{\n          'bmb_chat-bubble-profile-top': !message().isUserMessage,\n          'bmb_chat-bubble-profile-bottom': message().isUserMessage\n        }\"\n      >\n        @if (message().isUserMessage) {\n          <bmb-user-image\n            [size]=\"'mobile-small'\"\n            [image]=\"message().userProfile!\"\n            [altImage]=\"'Alt image description'\"\n            [bordered]=\"false\"\n          ></bmb-user-image>\n        } @else {\n          <bmb-icon\n            class=\"bmb_chat-bubble-profile-bot\"\n            [size]=\"20\"\n            alt=\"bot\"\n            [isSVGTemplate]=\"true\"\n          >\n            <ng-template #customIcon>\n              <bmb-bot-icon [iconName]=\"iconBotDefault()\" />\n            </ng-template>\n          </bmb-icon>\n        }\n      </div>\n      <div class=\"bmb_chat-bubble-msg-container\">\n        <div\n          class=\"bmb_chat-bubble-msg\"\n          [ngClass]=\"{\n            'bmb_chat-bubble-msg-userProfile-bottom': message().isUserMessage,\n            'bmb_chat-bubble-msg-top': !message().isUserMessage\n          }\"\n        >\n          @if (isThinking()) {\n            <div class=\"bmb_chat-bubble-msg-thinking-dots\">\n              <span class=\"bmb_chat-bubble-msg-thinking-dot\"></span>\n              <span class=\"bmb_chat-bubble-msg-thinking-dot\"></span>\n              <span class=\"bmb_chat-bubble-msg-thinking-dot\"></span>\n            </div>\n          } @else {\n            @if (message().type === 'mixed') {\n              <p>{{ message().content.text }}</p>\n              <img\n                class=\"bmb_chat-bubble-msg-image\"\n                [src]=\"message().content.imageUrl\"\n                alt=\"Message Img\"\n              />\n            }\n\n            @if (message().type === 'text') {\n              <p>{{ message().content.text }}</p>\n            }\n\n            @if (message().type === 'link') {\n              <bmb-text-link\n                [textLink]=\"message().content.text!\"\n                [textLinkStyle]=\"'underlined'\"\n                [target]=\"'_blank'\"\n                [link]=\"message().content.link!\"\n                [disabled]=\"false\"\n              ></bmb-text-link>\n            }\n\n            @if (message().type === 'options') {\n              <p>{{ message().content.text }}</p>\n              <div class=\"bmb_chat-bubble-msg-options-container\">\n                @for (item of message().content.options; track $index) {\n                  <bmb-container-button\n                    [componentTitle]=\"item.title\"\n                    [target]=\"item.target || '_blank'\"\n                    [link]=\"item.link || ''\"\n                    iconLeft=\"\"\n                    iconRight=\"\"\n                    [small]=\"true\"\n                    (onButton)=\"(item.onButton)\"\n                    [square]=\"true\"\n                  />\n                }\n              </div>\n            }\n\n            @if (message().type === 'template') {\n              <ng-container\n                *ngTemplateOutlet=\"message().content.template!\"\n              ></ng-container>\n            }\n          }\n        </div>\n        <div\n          class=\"bmb_chat-bubble-extra\"\n          [ngClass]=\"{\n            'bmb_chat-bubble-extra-user': message().isUserMessage\n          }\"\n        >\n          @if (message().isUserMessage) {\n            <p class=\"bmb_chat-bubble-extra-time\">\n              {{ message().time | date: 'hh:mm a' }}\n            </p>\n          } @else {\n            <div class=\"bmb_chat-bubble-extra-container\">\n              @if (gptIcons()) {\n                <bmb-icon\n                  class=\"bmb_chat-bubble-extra-icon\"\n                  icon=\"repeat\"\n                  [isFill]=\"true\"\n                  [size]=\"24\"\n                  (click)=\"handleRepeat($event)\"\n                  aria-label=\"button\"\n                  (keypress)=\"handleRepeat($event)\"\n                ></bmb-icon>\n                <bmb-icon\n                  class=\"bmb_chat-bubble-extra-icon\"\n                  icon=\"record_voice_over\"\n                  [isFill]=\"true\"\n                  [size]=\"24\"\n                  (click)=\"handleVoice($event)\"\n                  aria-label=\"button\"\n                  (keypress)=\"handleVoice($event)\"\n                ></bmb-icon>\n                <bmb-icon\n                  class=\"bmb_chat-bubble-extra-icon\"\n                  icon=\"content_copy\"\n                  [isFill]=\"true\"\n                  [size]=\"24\"\n                  (click)=\"handleCopyContent($event)\"\n                  aria-label=\"button\"\n                  (keypress)=\"handleCopyContent($event)\"\n                ></bmb-icon>\n                <bmb-icon\n                  class=\"bmb_chat-bubble-extra-icon\"\n                  icon=\"thumb_up\"\n                  [isFill]=\"true\"\n                  [size]=\"24\"\n                  (click)=\"handleLike($event)\"\n                  aria-label=\"button\"\n                  (keypress)=\"handleLike($event)\"\n                ></bmb-icon>\n                <bmb-icon\n                  class=\"bmb_chat-bubble-extra-icon\"\n                  icon=\"thumb_down\"\n                  [isFill]=\"true\"\n                  [size]=\"24\"\n                  (click)=\"handleDislike($event)\"\n                  aria-label=\"button\"\n                  (keypress)=\"handleDislike($event)\"\n                ></bmb-icon>\n              }\n            </div>\n            <p class=\"bmb_chat-bubble-extra-time\">\n              {{ message().time | date: 'hh:mm a' }}\n            </p>\n          }\n        </div>\n      </div>\n    </div>\n  </section>\n</section>\n";

